body:
{
  "pains": [
    {
      "id": "pain:tax-filed-wrong",
      "statement": "I pay them to file my payroll taxes and I still got the notice, so now I'm the one on the phone with the state.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A letter from a state agency or the IRS says a deposit was late, missing, or filed against the wrong account, after the provider's dashboard said the filing was handled.",
        "operational": "The owner or bookkeeper opens a ticket, re-sends the same forms, and then calls the state agency directly to get the account reopened or the penalty abated, across weeks or months while payroll keeps running on the same settings.",
        "personal": null,
        "personal_note": "No source shows the personal rung. The reviews on Capterra's Gusto and Paychex Flex pages stop at the operational cost ('takes them months to correct', 'don't get it handled promptly'). Nobody in public writes down what a tax notice does to their weekend or to how their partner or board sees them. Asked as q:pains-tax-personal."
      },
      "workflow": "The quarterly 941 and state withholding filings that Gusto, Paychex Flex or RUN file automatically, at the point where an agency notice arrives in the mail and the owner has to reconcile it against the provider's tax filings tab before the abatement window closes.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A state or federal agency notice lands with a deadline on it, which turns a filing the provider said was done into a dated task the business owns.",
          "cites": ["src:9"]
        },
        {
          "event": "An annual re-enrollment or account change at a state agency resets the employer registration, and filings start landing against the wrong account.",
          "cites": ["src:9"]
        },
        {
          "event": "ACA or year-end filing season, when every prior quarter's data gets resubmitted at once and errors surface together.",
          "cites": ["src:10"]
        }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "They weren't even planning on paying 1 out of the 3 of my state tax obligations",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "They lie about forms and tax filing",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Each year Paychex would re-enroll us and I would have to contact the state",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "The penalty and interest plus the hours of their own week spent on hold with an agency they were paying someone else to deal with.",
          "fears": "That there is a second filing wrong that nobody has found yet, and that they will find out the same way - by post, after the deadline.",
          "dream_outcome": "The filings are right, and if one is wrong the provider finds it, fixes it, and pays the penalty without the owner touching it."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "They consistently make mistakes which takes them months to correct",
              "cites": ["src:8"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Paychex just started withholding the max portion from the employee without ever saying a word to us.",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "Months of case management on something they signed off as working, and the credibility of having recommended the provider.",
          "fears": "That the error is systemic in how the account was configured, so correcting one quarter does not stop the next.",
          "dream_outcome": "A change to withholding or a filing never happens silently; every change shows up before it hits a paycheck."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Prior tax issues when they file them, they don't get it handled promptly",
              "cites": ["src:9"]
            },
            {
              "situation": "venting",
              "verbatim": "had some tax issues that they were unhelpful at resolving",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "The chasing lands on them: they are the one re-sending documents and holding the file open between the agency and the provider.",
          "fears": "No source shows the fear; both quotes stop at the provider being unhelpful and do not say what the person is afraid of.",
          "dream_outcome": "Somebody else owns the notice end to end and tells them when it is closed."
        }
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:payroll",
      "feature_note": "feat:payroll is the feature the company believes kills this ('files taxes'). The market's evidence is that automated filing removes the work but not the risk: what buyers complain about is not the filing, it is who owns the notice when a filing is wrong. The claim that survives contact with these quotes is about remediation, not automation.",
      "cites": ["src:5", "src:9", "src:8", "src:10", "src:1"]
    },
    {
      "id": "pain:nobody-picks-up",
      "statement": "Payroll is stuck, my money already left the account, and there is nobody at the payroll company I can get on the phone.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "The chat assistant loops to pages that do not exist, the support line is queued or closed for the weekend, and the ticket sits while a payday passes.",
        "operational": "Owners call back across several days and re-explain to a new agent each time, pay staff by personal transfer or paper cheque to cover the gap, and some start cancelling.",
        "personal": "The owner is the person standing in front of unpaid staff while the provider is unreachable, so the provider's silence lands as the owner's broken promise."
      },
      "workflow": "The payroll submission in Gusto or Paychex Flex on the day before payday, at the step where the run errors or a direct deposit does not land, and the only escalation path is a chat widget and a support line that is closed at the weekend.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A run errors or a deposit does not land the day before payday, when the only open channels are chat and a queue.",
          "cites": ["src:6"]
        },
        {
          "event": "Payday falls on a weekend or a holiday, when the support desk is closed.",
          "cites": ["src:5"]
        },
        {
          "event": "A login or account lockout that blocks the run entirely, which no self-service path can clear.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["economic_buyer", "champion", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "cannot get employees paid they have my money",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "Never a person to assist. AI sends you to tabs that don't exist",
              "cites": ["src:9"]
            },
            {
              "situation": "venting",
              "verbatim": "I have a hard time reaching an actual person",
              "cites": ["src:6"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Gusto missed one of our paydays",
              "cites": ["src:1"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "It's not worth the hassle",
              "cites": ["src:9"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "can be difficult to speak with anyone live when you need assistance",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "Wait times can be too long when contacting support",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "A payday they cannot make, plus the days of calling that come out of running the business.",
          "fears": "That the next time money is in transit and something breaks, the outcome is the same and there is no lever to pull.",
          "dream_outcome": "One phone number, a person who answers on payday, and the money moving on the day it was promised."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Customer support is inconcistent and poor.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "They never fully finished helping us get our platform set up.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "can be cost prohibitive and somewhat challenging to get support",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "They argued for this provider internally and now own every unanswered ticket in front of the person who approved it.",
          "fears": "That the setup or the escalation they were promised never gets finished and they carry it indefinitely.",
          "dream_outcome": "An escalation that actually escalates, with a named owner and a date."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "They are closed on the weekends when it comes to customer support.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "You are kind of left in the dark to figure it out yourself",
              "cites": ["src:9"]
            },
            {
              "situation": "venting",
              "verbatim": "Can't get hold of the account rep and customer service rep. No one would answer or return our calls.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "When issues arise, it can take days to get a response",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "The days between the question and the answer, during which they are the one telling colleagues they still do not know.",
          "fears": "That they will be blamed for a delay they have no way to shorten.",
          "dream_outcome": "Someone answers the same day, including on the weekend a payroll actually runs."
        }
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company touches this. Payroll, Benefits, Onboarding, Time tracking and Compliance are all product surface; this pain is about staffing and service levels behind the product. The nearest thing that would kill it is a support commitment (hours, a named human, an answer-time promise), which is an offer and operations decision, not a feature.",
      "cites": ["src:6", "src:9", "src:5", "src:3", "src:10", "src:1", "src:4", "src:12"]
    },
    {
      "id": "pain:revolving-rep",
      "statement": "Every time I get a payroll rep who actually knows my company, they get promoted and I start over with someone new.",
      "element": "b2b:ease_of_doing_business:commitment",
      "shape": {
        "surface": "The named account manager changes; the replacement does not know the company's pay codes or states, and answers come back as a promise to check with their manager.",
        "operational": "The office manager or HR lead re-explains the setup to each new rep, keeps their own notes outside the system, and routes urgent questions to whoever answers fastest rather than to the assigned person.",
        "personal": null,
        "personal_note": "No source shows it. Every quote on Capterra's Paychex Flex and RUN pages stops at the re-explaining and the 'let me check with my manager' reply; none says what the churn costs the person who has to keep re-teaching the account. Asked as q:pains-rep-personal."
      },
      "workflow": "The named-rep model at Paychex Flex and RUN, at the point where a question about a deduction, a state code or an off-cycle run goes to the assigned specialist and the reply is that they will check with their manager.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The assigned account manager is promoted or reassigned, which reviewers describe as a cycle rather than a one-off.",
          "cites": ["src:10"]
        },
        {
          "event": "An implementation or plan change hands the account to a new team part-way through setup.",
          "cites": ["src:10"]
        }
      ],
      "who_feels": ["end_user", "champion", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I don't like that the person we have currently doesn't return calls promptly",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "It's hard to get someone on the phone to answer questions, sometimes there is a revolving door",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "not having a dedicated contact",
              "cites": ["src:11"]
            },
            {
              "situation": "venting",
              "verbatim": "Contact person kept changing",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "The same explanation given over and over, and the loss of the shortcut a rep who knew the account used to give them.",
          "fears": "That something specific to their setup was only ever in one person's head and has now left with them.",
          "dream_outcome": "One person who knows the company, or a system where it does not matter who picks up."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "We had 3 account managers with Paychex Flex, the first 2 had challenges following thru on items",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "While we do have dedicated support on the account admin side these staff seem to change",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "This assigned person switches frequently and sometimes are unresponsive",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Items that do not get followed through, which they then have to chase personally.",
          "fears": "That the dedicated service they paid a premium for is a name on an email rather than a person with any continuity.",
          "dream_outcome": "Continuity: the account is handed over properly, and the replacement starts knowing what the last one knew."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "They switched our assigned payroll specialist so many times that I don't even know who it is now",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "Every time I get a payroll account manager who is knowledgeable, they always get promoted",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "They cannot vouch for the service they arranged, because they do not know who is currently responsible for it.",
          "fears": "That the knowledgeable rep is always temporary and the baseline is an entry-level one.",
          "dream_outcome": "A named contact who stays long enough to learn the account, or documentation good enough that nobody has to."
        }
      },
      "segments": ["seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company addresses this; it is a service-model pain in the incumbents' dedicated-rep design. For positioning it matters as the alternative buyers are currently suffering through, not as something a feature kills.",
      "cites": ["src:10", "src:9", "src:11"]
    },
    {
      "id": "pain:bill-creeps",
      "statement": "The per-person fee looked fine at five people, at twenty it's a line item I have to defend, and it went up without anyone telling me.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "The monthly invoice is higher than last month's, from per-employee-per-month pricing plus add-on modules, sometimes after a price rise that arrived with no notice.",
        "operational": "Owners re-price the plan, drop add-on modules, move contractors off the platform, and run a comparison against QuickBooks Payroll, RUN or Paychex Flex at renewal; cancelling still bills the full month.",
        "personal": null,
        "personal_note": "No source shows it. The quotes are all about the invoice and the budget; none says what defending the line item costs the person doing it. Asked as q:pains-price-personal."
      },
      "workflow": "The monthly invoice reconciled against headcount in Gusto or Paychex Flex, at the point where a new hire or a newly enabled module changes the per-employee-per-month total and the owner books it in QuickBooks alongside the payroll journal.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Headcount crosses the point where per-employee-per-month fees become a defensible line item rather than a rounding error.",
          "cites": ["src:3"]
        },
        {
          "event": "An annual price rise lands on the invoice without notice.",
          "cites": ["src:9"]
        },
        {
          "event": "Renewal or cancellation, when leaving still bills a full month.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The prices have gone up recently which I am not thrilled about.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "The price. Running payroll for a single employee costs too much",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "It costs too much for what it does",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "At times they increase costs without notification",
              "cites": ["src:9"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "In the end my annual budget tripled for 1 year. At times I would pay up to $153.00 per month",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "The expense of adding employees adds up quickly",
              "cites": ["src:8"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "they charged the full months fee anyway",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Real money at a scale that matters to a business running payroll for a handful of people, and a budget number they cannot forecast because it moves without warning.",
          "fears": "That the price is designed to climb with them, so every hire quietly makes the software more expensive than it was quoted.",
          "dream_outcome": "A price they can predict a year out, that does not change without being told, and that does not punish them for hiring."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "can get a bit pricey as your business grows",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "can be cost prohibitive and somewhat challenging to get support",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "They have to make the growth case for a tool whose cost grows automatically with the thing they are being measured on.",
          "fears": "That cost becomes the reason the tool gets replaced, and the replacement lands on them.",
          "dream_outcome": "Pricing that gets better per head as the company grows, not worse."
        }
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "brain/company lists no pricing or packaging feature, so nothing in the artifact kills this. What would kill it is a packaging decision - a predictable price, notice before a rise, no full-month charge on cancellation. That belongs to the offer step, not to a feature.",
      "cites": ["src:3", "src:2", "src:4", "src:9", "src:10", "src:8", "src:5"]
    },
    {
      "id": "pain:new-state-registration",
      "statement": "One hire in another state and suddenly I need a withholding account and an unemployment account there, and the payroll system won't open them for me.",
      "element": "b2b:ease_of_doing_business:expertise",
      "shape": {
        "surface": "Payroll cannot run for the new employee because the setup screen asks for state account numbers the business does not have, and in some places asks for a local jurisdiction the product does not support at all.",
        "operational": "The bookkeeper or outside accountant registers with each agency by hand, waits for account numbers that arrive over days or weeks, enters them into the payroll product, and for unsupported local taxes files outside the system entirely.",
        "personal": null,
        "personal_note": "No source shows it. Both quotes are about what the product will not do; neither says what the registration work costs the person doing it. Asked as q:pains-registration-personal."
      },
      "workflow": "The new-hire setup screen in Gusto or RUN for an employee in a state the company has never paid in, at the step asking for the state withholding ID and the unemployment account number, and again for any local jurisdiction the product cannot handle.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The first hire in a state the business has never paid into, which creates registration obligations before the first run can happen.",
          "cites": ["src:2"]
        },
        {
          "event": "An employee moving to a state or local jurisdiction the provider does not support.",
          "cites": ["src:11"]
        }
      ],
      "who_feels": ["technical_evaluator", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Wish they would handle the state registrations.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Unbilled or thinly billed hours on agency paperwork for each client that hires across a state line, on a clock set by the client's start date.",
          "fears": "That a registration missed on one client becomes a notice and a penalty they get blamed for, because they are the one the client thinks handles tax.",
          "dream_outcome": "The payroll product opens the state accounts as part of adding the employee, so the registration is a setup step rather than a separate project."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "cannot handle multiple local jurisdictions",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "A parallel manual process for the jurisdictions the system will not cover, running alongside the automated one.",
          "fears": "That the gap between what the system covers and what the law requires is invisible until an agency finds it.",
          "dream_outcome": "One system that covers every jurisdiction the company actually employs in, including local ones."
        }
      },
      "segments": ["seg:accountants", "seg:smb"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company opens state agency accounts. feat:compliance is described as 'required trainings, policies and benefits', which is a different thing. This is the clearest product gap the sweep found, and it sits squarely on the accountant segment, who are the ones doing the registrations by hand today. Whether Gusto in fact does state registration and it is simply missing from brain/company is asked as q:pains-state-registration.",
      "cites": ["src:2", "src:11"]
    },
    {
      "id": "pain:reports-you-cannot-pull",
      "statement": "The number my board or my client asks for isn't in any report I can build, so I take the closest one and finish the job by hand.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "The report library is a fixed set of templates with vague names, custom reports cannot be built, and the breakdown needed - by department, earning code, deduction or client entity - is not a field in any of them.",
        "operational": "Accountants and finance leads settle for the nearest canned report and assemble the missing figure outside the product each period; some stop recommending the provider over it.",
        "personal": null,
        "personal_note": "No source shows it. Reporting complaints appear even in five-star reviews, which suggests it is tolerated rather than escalated, and nobody writes down what the rebuild costs them personally. Asked as q:pains-reports-personal."
      },
      "workflow": "Month-end and year-end close in QuickBooks Online, at the step where a payroll figure split by department, earning code or client entity has to come out of Gusto, Paychex Flex or RUN and the report builder has no field for it.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Month-end or year-end close, when an accountant needs a cut of payroll the canned reports do not carry.",
          "cites": ["src:1", "src:10"]
        },
        {
          "event": "A provider switch, when the prior year's numbers have to be reproduced in the new system.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["technical_evaluator", "champion", "economic_buyer"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Creating customized reports are nearly impossible.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I have not found their reports to be as numerous and varied as some other payroll companies.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Their reporting is definitely a very important feature that in Paychex Flex is not intuitive",
              "cites": ["src:10"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "I wouldn't really recommend it.",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "Rebuild time every close, multiplied by every client on the platform, on work the client assumes is a button.",
          "fears": "That a number they assembled by hand is wrong, and that it is their name on the statement rather than the software's.",
          "dream_outcome": "A report builder with the fields they actually close on, so the export is the answer rather than the raw material."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Reporting was sometimes difficult to pull the information we wanted",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "not as much customizability with reports, special deductions/earning codes",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "The reporting is also not intuitive, the wording used for templated report names is vague",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "Hours per reporting cycle, and the awkwardness of asking for a number they are supposed to already have.",
          "fears": "That when leadership asks a new question of payroll data, the honest answer is that the system cannot answer it.",
          "dream_outcome": "Any question about payroll answerable from the product in one pass, with the earning and deduction codes the company actually uses."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "It's hard to create and review reports.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "reports are hard for me to find",
